"""Offline instruction pair similarity computation using SigLIP text encoder."""

import json
import pickle
from pathlib import Path
from typing import Dict, List, Set

import torch
import torch.nn.functional as F


class InstructionPairIndex:
    """Pre-computed instruction pair similarities for transfer loss.

    Stores SigLIP embeddings and a cosine similarity matrix for all unique
    instructions. Positive pairs are those with similarity > threshold.
    """

    def __init__(
        self,
        instructions: List[str],
        embeddings: torch.Tensor,
        sim_matrix: torch.Tensor,
        sim_threshold: float = 0.85,
    ):
        self.instructions = instructions
        self.instr_to_idx: Dict[str, int] = {instr: i for i, instr in enumerate(instructions)}
        self.embeddings = embeddings
        self.sim_matrix = sim_matrix
        self.sim_threshold = sim_threshold

        self.positive_sets: Dict[int, Set[int]] = {}
        for i in range(len(instructions)):
            positives = set()
            for j in range(len(instructions)):
                if i != j and sim_matrix[i, j].item() > sim_threshold:
                    positives.add(j)
            self.positive_sets[i] = positives

    def is_positive_pair(self, instr_a: str, instr_b: str) -> bool:
        a = self.instr_to_idx.get(instr_a.lower().strip())
        b = self.instr_to_idx.get(instr_b.lower().strip())
        if a is None or b is None:
            return False
        return b in self.positive_sets.get(a, set())

    def get_positives(self, instruction: str) -> List[str]:
        idx = self.instr_to_idx.get(instruction.lower().strip())
        if idx is None:
            return []
        return [self.instructions[j] for j in self.positive_sets.get(idx, set())]

    def get_embedding(self, instruction: str):
        idx = self.instr_to_idx.get(instruction.lower().strip())
        if idx is None:
            return None
        return self.embeddings[idx]

    def summary(self) -> str:
        n = len(self.instructions)
        n_pos_pairs = sum(len(v) for v in self.positive_sets.values()) // 2
        return (
            f"InstructionPairIndex: {n} instructions, "
            f"{n_pos_pairs} positive pairs (threshold={self.sim_threshold})"
        )

    @staticmethod
    def build(
        instructions: List[str],
        siglip_path: str,
        sim_threshold: float = 0.85,
        device: str = "cuda",
        batch_size: int = 32,
    ) -> "InstructionPairIndex":
        from transformers import AutoModel, AutoTokenizer

        model = AutoModel.from_pretrained(siglip_path).to(device)
        tokenizer = AutoTokenizer.from_pretrained(siglip_path)
        model.eval()

        normed = [instr.lower().strip() for instr in instructions]
        seen = set()
        unique = []
        for s in normed:
            if s not in seen:
                seen.add(s)
                unique.append(s)

        all_embeddings = []
        with torch.no_grad():
            for start in range(0, len(unique), batch_size):
                batch = unique[start : start + batch_size]
                inputs = tokenizer(
                    batch,
                    padding=True,
                    truncation=True,
                    max_length=64,
                    return_tensors="pt",
                ).to(device)
                text_features = model.get_text_features(**inputs)
                text_features = F.normalize(text_features, dim=-1)
                all_embeddings.append(text_features.cpu())

        embeddings = torch.cat(all_embeddings, dim=0)
        sim_matrix = embeddings @ embeddings.T

        del model
        torch.cuda.empty_cache()

        return InstructionPairIndex(unique, embeddings, sim_matrix, sim_threshold)

    def save(self, path: str):
        data = {
            "instructions": self.instructions,
            "embeddings": self.embeddings,
            "sim_matrix": self.sim_matrix,
            "sim_threshold": self.sim_threshold,
        }
        with open(path, "wb") as f:
            pickle.dump(data, f)

    @staticmethod
    def load(path: str) -> "InstructionPairIndex":
        with open(path, "rb") as f:
            data = pickle.load(f)
        return InstructionPairIndex(
            data["instructions"],
            data["embeddings"],
            data["sim_matrix"],
            data["sim_threshold"],
        )


def extract_all_instructions(paraphrases_path: str) -> List[str]:
    with open(paraphrases_path) as f:
        data = json.load(f)
    instructions = []
    for entry in data.values():
        instructions.append(entry["original"].lower().strip())
        for p in entry["paraphrases"]:
            instructions.append(p.lower().strip())
    return list(set(instructions))
